import { mkdirSync } from 'node:fs'
import { dirname, resolve } from 'node:path'
import { createClient } from '@libsql/client'
import { drizzle } from 'drizzle-orm/libsql'
import { migrate } from 'drizzle-orm/libsql/migrator'
import * as schema from './schema.ts'

/**
 * Opens the chat database and brings it up to date (02 §6).
 *
 * `url` is a libsql URL: `file:data/shopping.db`, or `:memory:` for tests.
 * Migrations (generated by `pnpm db:generate` into `drizzle/`) run on every open;
 * already-applied ones are skipped.
 */

const MIGRATIONS = resolve(import.meta.dirname, '../../drizzle')

export async function openDatabase(url: string) {
  if (url.startsWith('file:')) mkdirSync(dirname(url.slice('file:'.length)), { recursive: true })

  const client = createClient({ url })
  const db = drizzle(client, { schema })
  await db.run('PRAGMA foreign_keys = ON')
  await migrate(db, { migrationsFolder: MIGRATIONS })

  return Object.assign(db, { close: () => client.close() })
}

export type Database = Awaited<ReturnType<typeof openDatabase>>
